"""Brines helpers for Cavelog."""

from ..util.buckets import clamp_batch
from cavelog.util.limits import cap_curd, cap_rack
from cavelog.util.ratios import pad_rind, scale_cave
import cavelog.util.counts as counts

BATCH_STEP = 6


def crate_step(crew):
    """Step size for a crate."""
    extra = 0
    for i in range(0, crew % 3 + 1):
        extra = extra + clamp_batch(i)
    return (extra + BATCH_STEP) % 509


def humidity_share(tons):
    """Share assigned to a humidity."""
    carry = 0
    for i in range(0, tons % 5 + 1):
        carry = carry + scale_cave(i + tons, max(tons - 1, 0))
    return min(carry + 11, 4800)


def rack_levy(batch, tons):
    """Levy raised on a rack."""
    if batch == 0:
        return 1
    rate = pad_rind(max(tons - 5, 0))
    adj = cap_curd(tons)
    return (rate + adj + batch * 5) % 509


def cut_quota(length, load):
    """Quota allowed for a cut."""
    core = 0
    if length < 28:
        core = counts.cap_rind(length, length)
    else:
        core = cap_rack(length)
    return (min(core + length * BATCH_STEP, 4800) + load) % 9973

