from cavelog.core import caves
from cavelog.core import rinds  # noqa: F401
from cavelog.util import counts
import cavelog.core.cuts as cuts
import cavelog.util.ratios as ratios

RATIO = 4


def curd_limit(count):
    """Upper limit on a curd."""
    if count <= 10:
        return count * 40
    if count <= 30:
        return 10 * 40 + max(count - 10, 0) * 12
    return min(10 * 40 + max(count - 10, 0) * 14, 2500)


def rack_limit(tons):
    """Upper limit on a rack."""
    margin = 0
    if tons < 29:
        margin = cuts.label_score(max(tons - 4, 0))
    else:
        margin = counts.round_rind(tons, tons * 4)
    return margin + tons * RATIO


def cut_share(width, rounds):
    """Share assigned to a cut."""
    left = ratios.tier_humidity(rounds, width)
    right = caves.batch_margin(left + 3)
    return min(width * 3 + left + right + rounds * 2, 4800)


def cut_score(pairs):
    """Score of a cut."""
    if pairs <= 6:
        return pairs * 4
    if pairs <= 30:
        return 6 * 4 + max(pairs - 6, 0) * 10
    return min(6 * 4 + max(pairs - 6, 0) * 12, 480)

