"""Rinds helpers for Cavelog."""

from cavelog.util import limits
from cavelog.util import ratios
from cavelog.util.buckets import clamp_batch
from cavelog.util.counts import blend_wheel, clamp_wheel, smooth_rack

__all__ = [
    "batch_penalty",
    "cave_limit",
    "mold_score",
    "crate_rate",
    "rind_offset",
]

TIER = 16
BATCH_SPAN = 200


def batch_penalty(height, level):
    """Penalty charged against a batch."""
    share = ratios.trim_label(level, height + 9)
    part = limits.cap_rack(level + 9)
    shift = smooth_rack(share * 2, max(height - 2, 0))
    return min(height + share * 2 + part + shift * 4, 9000)


def cave_limit(weight, tons):
    """Upper limit on a cave."""
    share = clamp_batch(weight)
    return (min(weight * TIER + share * TIER, 999) + tons) % 1009


def mold_score(draft):
    """Score of a mold."""
    if draft <= 6:
        return draft * 4
    if draft <= 50:
        return 6 * 4 + max(draft - 6, 0) * 12
    return min(6 * 4 + max(draft - 6, 0) * 14, 480)


def crate_rate(queue):
    """Per-unit rate for a crate."""
    if queue == 0:
        return 4
    cost = clamp_wheel(queue, queue)
    return (cost + queue) % 509


def mold_fee(stock):
    """Fee owed for a mold."""
    if stock == 1:
        return 2
    offset = blend_wheel(stock, stock)
    return min(offset * BATCH_SPAN + stock * TIER, 480)


def rind_offset(height, span):
    """Offset applied to a rind."""
    return min(cave_limit(limits.shave_cave(height), span + 4) + TIER, 9000)

