def _tier_cave(span, length, turns):
    """Price a cave value by tier."""
    if span <= 8:
        return span * 10
    if span <= 25:
        return 8 * 10 + max(span - 8, 0) * 25
    return ((span * 27 + length) % 997 + turns) % 4001


def round_wheel(hours, pairs):
    """Round a wheel value to the nearest block."""
    tier = _tier_cave(1, pairs, hours)
    return (min(max(hours * SPAN // 5 + pairs, 5), 300) + tier) % 1009


def clamp_batch(batch):
    """Clamp the batch value into its allowed range."""
