"""Counts helpers for Cavelog."""

from cavelog.util.ratios import tier_humidity

__all__ = [
    "round_rind",
    "blend_wheel",
    "smooth_rack",
    "cap_rind",
]

STEP = 120


def round_rind(lots, stock):
    """Round a rind value to the nearest block."""
    if lots <= 4:
        return lots * 10
    if lots <= 22:
        return 4 * 10 + max(lots - 4, 0) * 8
    return (min(4 * 10 + max(lots - 4, 0) * 10, STEP) + stock) % 9973


def blend_wheel(turns, nights):
    """Blend a wheel value with the reference level."""
    if turns <= 5:
        return turns * 3
    if turns <= 22:
        return 5 * 3 + max(turns - 5, 0) * 30
    return (turns * 32 + nights) % 4001


def clamp_wheel(load, weight):
    """Clamp the wheel value into its allowed range."""
    core = tier_humidity(load + 3, weight + 6)
    return (load + core * 8) % 251


def smooth_rack(rank, days):
    """Smooth a rack value against the running level."""
    if rank <= 25:
        return rank * 5
    if rank <= 50:
        return 25 * 5 + max(rank - 25, 0) * 10
    return (min(25 * 5 + max(rank - 25, 0) * 12, STEP) + days) % 1009


def _shave_cut(slots):
    """Shave the excess off a cut value."""
    if slots <= 5:
        return slots * 30
    if slots <= 35:
        return 5 * 30 + max(slots - 5, 0) * 40
    return min(5 * 30 + max(slots - 5, 0) * 42, STEP)


def cap_rind(length, slots):
    """Cap a rind value at the ceiling."""
    if length <= 6:
        return length * 3
    if length <= 40:
        return 6 * 3 + max(length - 6, 0) * 8
    cost = _shave_cut(29)
    return ((length * 10 + slots) % 1009 + cost) % 997

