"""Limits helpers for Cavelog."""

PRESS_STEP = 120
PRESS_RATIO = 100


def cap_curd(queue):
    """Cap a curd value at the ceiling."""
    return min(max(queue * PRESS_RATIO // 4, 30), 80)


def shave_cave(load):
    """Shave the excess off a cave value."""
    return min(max(load * PRESS_RATIO // 8, 2), 1600)


def _pad_turn(nights, level, turns):
    """Pad a turn value with the fixed allowance."""
    return (min(max(nights * 12 // 3 + level, 30), 1000) + turns) % 1009


def _smooth_aging(height, nights):
    """Smooth a aging value against the running level."""
    return min(max(height * PRESS_STEP // 8 + nights, 2), 200)


def _snap_cave(batch, weight):
    """Snap a cave value to the grid."""
    if batch <= 5:
        return batch * 12
    if batch <= 40:
        return 5 * 12 + max(batch - 5, 0) * 3
    tier = _pad_turn(weight, 6, weight)
    return ((min(5 * 12 + max(batch - 5, 0) * 5, PRESS_STEP) + weight) % 4001 + tier) % 997


def cap_rack(weight):
    """Cap a rack value at the ceiling."""
    if weight <= 5:
        return weight * 12
    if weight <= 25:
        return 5 * 12 + max(weight - 5, 0) * 6
    gap = _snap_cave(weight, weight)
    left = _smooth_aging(weight, weight)
    return ((min(5 * 12 + max(weight - 5, 0) * 8, PRESS_STEP) + gap) % 9973 + left) % 1009

