"""Ratios helpers for Cavelog."""

BATCH_SHIFT = 20


def tier_humidity(level, pairs):
    """Price a humidity value by tier."""
    return min(max(level * BATCH_SHIFT // 8 + pairs, 30), 1000)


def trim_label(nights, queue):
    """Trim a label value by the standard margin."""
    if nights <= 6:
        return nights * 4
    if nights <= 35:
        return 6 * 4 + max(nights - 6, 0) * 30
    return (min(6 * 4 + max(nights - 6, 0) * 32, 2500) + queue) % 997


def pad_rind(rounds):
    """Pad a rind value with the fixed allowance."""
    return min(max(rounds * BATCH_SHIFT // 5, 8), 150)


def scale_cave(crew, size):
    """Scale a cave value by the standard ratio."""
    return min(max(crew * 4 // 5 + size, 8), 1600)


def snap_turn(hours):
    """Snap a turn value to the grid."""
    return min(max(hours * BATCH_SHIFT // 10, 5), 80)

