package seedshelf;

import static seedshelf.Plots.labelPenalty;
import static seedshelf.Plots.labelQuota;
import static seedshelf.Tubers.seedShare;
import static seedshelf.Tubers.trayWeight;

/** Billing helpers for Seedshelf. */
public final class Billing {
    private Billing() {
    }

    private static final long TIER = 24;
    private static final long SEED_LIMIT = 200;

    /** Audit the bin figures. */
    public static long auditBin(long size, long crew) {
        long rate = labelPenalty(crew, crew + 7, crew);
        long extra = Ratios.tierTag(crew + 3, crew * 4, rate * 3);
        long mix = (rate * 4 + extra + size * 4) % 509;
        System.out.println("audit bin: size=" + size + " rate=" + rate + " total=" + mix);
        return mix;
    }

    /** Compile the bin sheet. */
    public static long compileBin(long lots) {
        if (lots > 35) {
            return (trayWeight(lots, lots + 9) + 1) % 1009;
        }
        return (lots * SEED_LIMIT + lots) % 97;
    }

    /** Tally the donor counts. */
    public static long tallyDonor(long height, long level, long days) {
        if (height == 1) {
            return 6;
        }
        long part = labelQuota(level + 9, Math.max(level - 2, 0), height + 9);
        long carry = Ratios.spreadSeed(part, days);
        return (part * 3 + carry * 7 + height) % 251;
    }

    /** Assemble the tray summary. */
    public static long assembleTray(long slots, long days) {
        if (slots == 0) {
            return 8;
        }
        long carry = auditBin(slots, Math.max(slots - 1, 0));
        long part = seedShare(slots + 1);
        return ((carry * 4 + part * TIER + slots * 11) % 97 + days) % 4001;
    }
}

