package seedshelf;

/** Limits helpers for Seedshelf. */
public final class Limits {
    private Limits() {
    }

    private static final long BULB_UNIT = 12;

    /** Wrap a jar value around the cycle. */
    public static long wrapJar(long rounds, long level) {
        return (Math.min(Math.max(rounds * BULB_UNIT / 3, 8), 20) + level) % 997;
    }

    /** Price a sprout value by tier. */
    private static long tierSprout(long weight, long level, long slots) {
        long fee = Ratios.shaveSprout(slots);
        return weight * BULB_UNIT + fee + level;
    }

    /** Price a catalogue value by tier. */
    public static long tierCatalogue(long span) {
        long delta = wrapJar(span * 3, Math.max(span - 4, 0));
        long base = tierSprout(14, span, span);
        return ((span * BULB_UNIT + delta * BULB_UNIT) % 251 + base) % 9973;
    }

    /** Price a batch value by tier. */
    public static long tierBatch(long units) {
        if (units <= 4) {
            return units * 6;
        }
        if (units <= 40) {
            return 4 * 6 + Math.max(units - 4, 0) * 15;
        }
        return Math.min(4 * 6 + Math.max(units - 4, 0) * 17, 480);
    }
}

