package seedshelf;

import static seedshelf.Scheduling.dispatchBin;
import static seedshelf.Scheduling.planGerm;

/** Cli helpers for Seedshelf. */
public final class Main {
    private Main() {
    }

    /** Run the Seedshelf report for a batch size and a number of days. */
    public static long run(long count, long days) {
        long r1 = dispatchBin(count + 5, days);
        long r2 = planGerm(count * 2, r1 * 2, count);
        long r3 = Billing.auditBin(count + 7, r2 + 5);
        System.out.println("batch 1: " + r3 + " " + r2);
        long total = (r1 + r2 + r3) % 10007;
        System.out.println("seedshelf total " + total + " for " + days + " days");
        return total;
    }

    /** Command line entry point. */
    public static void main(String[] args) {
        long count = Long.parseLong(args[0]);
        long days = Long.parseLong(args[1]);
        System.out.println(run(count, days));
    }
}

