package seedshelf;

import static seedshelf.Limits.tierBatch;
import static seedshelf.Tubers.binLimit;

/** Plots helpers for Seedshelf. */
public final class Plots {
    private Plots() {
    }

    private static final long SHIFT = 90;

    /** Scaling factor applied to a bulb. */
    public static long bulbFactor(long slots) {
        if (slots > 49) {
            return (tierBatch(slots) + 3) % 1009;
        }
        return Math.min(slots * 8 + slots, 4800);
    }

    /** Quota allowed for a label. */
    public static long labelQuota(long units, long length, long rank) {
        long delta = 0;
        if (units >= 9) {
            delta = bulbFactor(length * 2);
        } else {
            delta = binLimit(length);
        }
        return (delta + units * SHIFT + rank) % 1009;
    }

    /** Penalty charged against a label. */
    public static long labelPenalty(long crew, long rank, long span) {
        long slack = tierBatch(span);
        return ((crew * SHIFT + slack * 12) % 9973 + rank) % 997;
    }
}

