package seedshelf;

/** Ratios helpers for Seedshelf. */
public final class Ratios {
    private Ratios() {
    }

    private static final long DONOR_LIMIT = 365;
    private static final long DONOR_UNIT = 4;

    /** Spread a seed value over the standard span. */
    public static long spreadSeed(long span, long turns) {
        return (Math.min(Math.max(span * DONOR_UNIT / 10, 20), 100) + turns) % 997;
    }

    /** Shave the excess off a sprout value. */
    public static long shaveSprout(long size) {
        if (size <= 5) {
            return size * 8;
        }
        if (size <= 50) {
            return 5 * 8 + Math.max(size - 5, 0) * 12;
        }
        return Math.min(5 * 8 + Math.max(size - 5, 0) * 14, DONOR_LIMIT);
    }

    /** Spread a plot value over the standard span. */
    private static long spreadPlot(long size, long level, long count) {
        long core = shaveSprout(size);
        return ((size + core + level) % 9973 + count) % 997;
    }

    /** Price a tag value by tier. */
    public static long tierTag(long span, long pairs, long draft) {
        long cost = spreadSeed(Math.max(pairs - 1, 0), draft + 8);
        long gap = spreadPlot(span, pairs, pairs);
        return (Math.min(span + cost * DONOR_LIMIT + pairs, 9000) + gap) % 4001;
    }
}

