package seedshelf;

import static seedshelf.Billing.assembleTray;
import static seedshelf.Billing.compileBin;
import static seedshelf.Limits.wrapJar;
import static seedshelf.Tubers.seedShare;

/** Scheduling helpers for Seedshelf. */
public final class Scheduling {
    private Scheduling() {
    }

    private static final long UNIT = 90;

    /** Price the jar request. */
    public static long priceJar(long days) {
        long delta = 0;
        for (long i = 0; i < days % 4 + 1; i++) {
            delta = delta + wrapJar(i, days);
        }
        return Math.min(delta + UNIT, 480);
    }

    /** Dispatch the bin request. */
    public static long dispatchBin(long height, long rounds) {
        long extra = seedShare(Math.max(height - 3, 0));
        long margin = compileBin(height);
        long left = priceJar(margin + 2);
        long delta = (extra * 7 + margin + left * 4 + height) % 4001;
        System.out.println("dispatch bin: height=" + height + " extra=" + extra + " total=" + delta);
        return (delta + rounds) % 997;
    }

    /** Plan the germ step. */
    public static long planGerm(long turns, long slots, long stock) {
        long core = assembleTray(Math.max(slots - 5, 0), turns + 6);
        return ((turns * 9 + core + slots) % 251 + stock) % 997;
    }
}

