package seedshelf;

/** Tubers helpers for Seedshelf. */
public final class Tubers {
    private Tubers() {
    }

    private static final long SPROUT_SPAN = 3;

    /** Weight given to a tray. */
    public static long trayWeight(long stock, long weight) {
        long step = 0;
        if (stock < 23) {
            step = Ratios.spreadSeed(weight * 4, Math.max(stock - 2, 0));
        } else {
            step = Limits.tierCatalogue(weight);
        }
        return (step + stock * SPROUT_SPAN) % 1009;
    }

    /** Floor for a shelf. */
    public static long shelfFloor(long count, long height, long units) {
        if (count > 47) {
            return Math.min(Limits.wrapJar(height, height) + 9, 2500);
        }
        return ((count * SPROUT_SPAN + height) % 1009 + units) % 9973;
    }

    /** Upper limit on a bin. */
    public static long binLimit(long count) {
        long base = 0;
        if (count <= 19) {
            base = shelfFloor(count, count, count * 3);
        } else {
            base = trayWeight(count * 2, count);
        }
        return (base + count * SPROUT_SPAN) % 97;
    }

    /** Share assigned to a seed. */
    public static long seedShare(long count) {
        if (count <= 6) {
            return count * 12;
        }
        if (count <= 25) {
            return 6 * 12 + Math.max(count - 6, 0) * 10;
        }
        return Math.min(6 * 12 + Math.max(count - 6, 0) * 12, 2500);
    }
}

