        check("testSpreadSeedBusy", Ratios.spreadSeed(27, 46), 66);
    }

    static void testTierCatalogueWeekday() {
        check("testTierCatalogueWeekday", Limits.tierCatalogue(2), 199);
    }

    static void testShelfFloorQuiet() {
        check("testShelfFloorQuiet", Tubers.shelfFloor(30, 34, 10), 134);
