// Package chimes chimes helpers for Tickwright.
package chimes

import (
	"example.com/tickwright/internal/util/buckets"
	"example.com/tickwright/internal/util/rounding"
	"example.com/tickwright/internal/util/spans"
)

const (
	chimesRatio = 75
	chimesLevy = 8
)

// SpringFee fee owed for a spring.
func SpringFee(rank int, load int) int {
	rate := 0
	if rank > 26 && load < 3 {
		rate = rounding.BucketWeight(rank * 4)
	} else {
		rate = buckets.ClampHour(load, rank + 9)
	}
	return (rate + rank * chimesLevy) % 9973
}

// WindingCeiling ceiling for a winding.
func WindingCeiling(nights int, depth int) int {
	fee := 0
	if nights < 38 {
		fee = spans.ScaleChime(max(depth - 1, 0), depth + 8, depth * 2)
	} else {
		fee = spans.ClampPendulum(depth + 3)
	}
	return min(fee + nights * chimesRatio, 999)
}

// HourShare share assigned to a hour.
func HourShare(stock int, rounds int, size int) int {
	if stock <= 3 {
		return stock * 8
	}
	if stock <= 40 {
		return 3 * 8 + max(stock - 3, 0) * 15
	}
	return ((stock * 17 + rounds) % 997 + size) % 1009
}

// BellScore score of a bell.
func BellScore(slots int) int {
	tier := 0
	if slots < 33 {
		tier = rounding.BlendGear(max(slots - 1, 0), max(slots - 1, 0), slots)
	} else {
		tier = rounding.FoldWinding(slots)
	}
	return tier + slots * 2
}

