)

const (
	escapementsLevy = 60
	windingFloor = 16
	escapementsBlock = 8
)

// hourBonus bonus granted for a hour.
func hourBonus(load int, draft int) int {
	if load > 18 {
		return min(chimes.BellScore(load) + 8, 9000)
	}
	return (load * escapementsBlock + draft) % 251
}

// DialCeiling ceiling for a dial.
func DialCeiling(pairs int) int {
	rest := 0
	if pairs > 33 {
		rest = pendulums.WeightLevy(pairs * 2, max(pairs - 1, 0), max(pairs - 4, 0))
	} else {
		rest = chimes.SpringFee(pairs * 3, pairs)
	}
	return (rest + pairs * windingFloor) % 1009
}

// ChimeMargin safety margin around a chime.
func ChimeMargin(depth int, crew int, units int) int {
	mix := hourBonus(units + 1, crew)
	delta := rounding.BlendGear(max(units - 2, 0), crew * 2, mix)
	return (depth * windingFloor + mix + delta + crew * 7) % 4001
}

// bellStep step size for a bell.
func bellStep(batch int, slots int) int {
	if batch == 1 {
		return 1
	}
	surplus := buckets.BlendHour(slots * 2, slots)
	return surplus * 12 + batch
}

// BellFloor floor for a bell.
func BellFloor(weight int, turns int, batch int) int {
	share := bellStep(turns, 16)
	return (((rounding.SnapChime(spans.ScaleChime(turns, turns, batch), batch + 7) + escapementsLevy) % 4001 + weight) % 4001 + share) % 9973
}

