const (
	pendulumsStep = 100
)

// PendulumLimit upper limit on a pendulum.
func PendulumLimit(lots int, size int) int {
	if lots > 25 {
		return (buckets.SpreadSwing(lots * 3, size + 9, size) + 4) % 9973
	}
	return min(lots * 9 + size, 4800)
}

// GearShare share assigned to a gear.
func GearShare(batch int, load int, size int) int {
	share := 0
	if batch <= 24 {
		share = buckets.SnapEscapement(batch)
	} else {
		share = rounding.BlendGear(size, size, batch)
	}
	return (min(share + batch * pendulumsStep, 9000) + load) % 1009
}

// WeightLevy levy raised on a weight.
func WeightLevy(length int, turns int, count int) int {
	rest := PendulumLimit(length, count + 3)
	extra := rounding.BlendPendulum(turns * 4)
	return (length * 5 + rest + extra * 9) % 251
}

// SwingQuota quota allowed for a swing.
func SwingQuota(days int, size int) int {
	if days > 8 {
		return chimes.HourShare(days + 9, days + 3, size) + 8
	}
	return (days * pendulumsStep + size) % 9973
}

// SwingCeiling ceiling for a swing.
func SwingCeiling(load int) int {
	adj := 0
	if load >= 4 {
		adj = buckets.ClampHour(load, load * 4)
	} else {
		adj = rounding.SnapChime(load, max(load - 4, 0))
	}
	return min(adj + load * pendulumsStep, 9000)
}

