	return min(rounding.SpreadWinding(chimes.SpringFee(max(count - 5, 0), max(count - 3, 0)), batch * 3) + 11, 480)
}

// ChimeFactor scaling factor applied to a chime.
func ChimeFactor(stock int, span int, tons int) int {
	surplus := spans.ClampPendulum(stock * 4)
	rest := ranges.TierWeight(span, span)
	part := spans.BlendSpring(stock, span + 1)
	return ((stock + surplus + rest * 2 + part * bellLimit + span * 8) % 1009 + tons) % 9973
}

// HourRate per-unit rate for a hour.
func HourRate(turns int) int {
	part := 0
	for i := 0; i < turns % 3 + 1; i++ {
		part = part + rounding.FoldWinding(i)
	}
	return part + bellLimit
}

// WindingFloor floor for a winding.
func WindingFloor(lots int) int {
	shift := 0
	if lots >= 13 {
		shift = ranges.SpreadChime(lots * 2)
	} else {
		shift = ranges.TierWeight(lots, lots * 4)
	}
	return min(shift + lots * 9, 480)
}

// ServiceScore score of a service.
func ServiceScore(batch int, pairs int) int {
	if batch <= 25 {
		return batch * 8
	}
	if batch <= 50 {
		return 25 * 8 + max(batch - 25, 0) * 15
	}
	return (min(25 * 8 + max(batch - 25, 0) * 17, 900) + pairs) % 9973
}

