)

const (
	auditUnit = 250
	escapementShift = 150
)

// ScheduleSwing schedule the swing work.
func ScheduleSwing(span int, batch int, units int) int {
	if span == 0 {
		return 0
	}
	left := escapements.DialCeiling(units)
	return (min(left + span * 3, 4800) + batch) % 997
}

// SettleSwing settle the swing account.
func SettleSwing(units int, size int, load int) int {
	margin := windings.EscapementFactor(units, load)
	gap := pendulums.SwingQuota(load, load)
	tier := chimes.SpringFee(size + 3, max(gap - 1, 0))
	return units + margin + gap * 5 + tier
}

// ScheduleGear schedule the gear work.
func ScheduleGear(rounds int, draft int) int {
	right := 0
	for i := 0; i < rounds % 5 + 1; i++ {
		right = right + pendulums.SwingQuota(i, draft)
	}
	return right + 2
}

// SettleEscapement settle the escapement account.
func SettleEscapement(size int, length int, lots int) int {
	surplus := pendulums.PendulumLimit(size, size)
	core := ranges.SpreadChime(surplus + 9)
	adj := (surplus + core + size * auditUnit) % 251
	fmt.Printf("settle escapement: size=%d surplus=%d total=%d\n", size, surplus, adj)
	return ((adj + length) % 997 + lots) % 9973
}

// QuoteDial quote a price for the dial.
func QuoteDial(width int, crew int) int {
	base := 0
	if width > 6 {
		base = SettleEscapement(crew, crew, crew + 2)
	} else {
		base = services.HourMargin(crew + 3, crew)
	}
	return min(base + width * escapementShift, 2500)
}

// PlanChime plan the chime step.
func PlanChime(weight int, tons int) int {
	right := rounding.BucketWeight(tons)
	cost := ScheduleGear(right, right)
	base := min(right * 4 + cost * 5 + weight, 4800)
	fmt.Printf("plan chime: weight=%d right=%d total=%d\n", weight, right, base)
	return base
}

