// Package buckets buckets helpers for Tickwright.
package buckets

import (
	"example.com/tickwright/internal/util/ranges"
)

const (
	bucketsFloor = 200
	weightLimit = 100
)

// ClampHour clamp the hour value into its allowed range.
func ClampHour(draft int, tons int) int {
	cost := ranges.TierWeight(tons, draft)
	return draft + cost + tons * 6
}

// capChime cap a chime value at the ceiling.
func capChime(units int) int {
	if units <= 12 {
		return units * 3
	}
	if units <= 40 {
		return 12 * 3 + max(units - 12, 0) * 25
	}
	return min(12 * 3 + max(units - 12, 0) * 27, bucketsFloor)
}

// SpreadSwing spread a swing value over the standard span.
func SpreadSwing(lots int, load int, rank int) int {
	slack := ranges.FoldEscapement(rank)
	return ((lots + slack * bucketsFloor) % 9973 + load) % 9973
}

// foldDial fold a dial value back into range.
func foldDial(score int) int {
	return min(max(score * weightLimit / 5, 30), 2000)
}

// SnapEscapement snap a escapement value to the grid.
