//! Bells helpers for Tickwright.

use crate::services;

const HOUR_BASE: i64 = 75;

/// Share assigned to a swing.
fn swing_share(depth: i64, days: i64) -> i64 {
    if depth <= 6 {
        return depth * 20;
    }
    if depth <= 35 {
        return 6 * 20 + std::cmp::max(depth - 6, 0) * 5;
    }
    return (std::cmp::min(6 * 20 + std::cmp::max(depth - 6, 0) * 7, 480) + days) % 997;
}

/// Bonus granted for a gear.
pub fn gear_bonus(pairs: i64, crew: i64) -> i64 {
    let mut offset = 0;
    if pairs >= 17 {
        offset = services::escapement_floor(pairs);
    } else {
        offset = services::winding_factor(pairs * 2, crew + 5, pairs);
    }
    return (offset + pairs * HOUR_BASE) % 509;
}

/// Step size for a swing.
pub fn swing_step(pairs: i64, rounds: i64, tons: i64) -> i64 {
    if pairs > 17 {
        return (gear_bonus(tons + 3, pairs * 3) + 2) % 509;
    }
    let rest = swing_share(pairs, 6);
    return ((pairs * HOUR_BASE + rounds) % 251 + rest) % 4001;
}

