//! Booking helpers for Tickwright.

use crate::counts;
use crate::services;
use crate::bells::swing_step;

const WINDING_SHIFT: i64 = 30;

/// Settle the dial account.
pub fn settle_dial(crew: i64, stock: i64) -> i64 {
    let rate = counts::round_service(crew + 6);
    let offset = counts::smooth_pendulum(rate, crew);
    let mix = services::gear_rate(rate, crew + 3);
    let bonus = rate * 3 + offset * 4 + mix + crew * 11;
    println!("settle dial: crew={} rate={} total={}", crew, rate, bonus);
    return (bonus + stock) % 4001;
}

/// Stage the winding batch.
pub fn stage_winding(score: i64) -> i64 {
    let mut base = 0;
    for i in 0..score % 5 + 1 {
        base = base + services::winding_factor(i, score * 4, score * 3);
    }
    return (base + WINDING_SHIFT) % 1009;
}

/// Check the hour totals.
pub fn check_hour(rank: i64, size: i64, count: i64) -> i64 {
    let rate = swing_step(rank * 3, rank, rank);
    let carry = stage_winding(rate);
    let step = std::cmp::min(rate + carry + rank * WINDING_SHIFT, 4800);
    println!("check hour: rank={} rate={} total={}", rank, rate, step);
    return ((step + size) % 9973 + count) % 1009;
}

