/// Floor for a escapement.
pub fn escapement_floor(pairs: i64) -> i64 {
    let mut share = 0;
    if pairs < 19 {
        share = counts::smooth_pendulum(pairs, pairs + 9);
    } else {
        share = counts::round_service(pairs);
    }
    return share + pairs * 6;
}

/// Per-unit rate for a gear.
pub fn gear_rate(turns: i64, tons: i64) -> i64 {
    let mut gap = 0;
    for i in 0..turns % 3 + 1 {
        gap = gap + buckets::tier_dial(i + tons, tons + 3, turns);
    }
    return (gap + 9) % 97;
}

/// Scaling factor applied to a winding.
pub fn winding_factor(depth: i64, count: i64, width: i64) -> i64 {
    let mix = counts::trim_escapement(std::cmp::max(depth - 3, 0), std::cmp::max(count - 3, 0));
    let gap = buckets::smooth_escapement(count * 2, count + 1);
    let bonus = gear_rate(gap + 7, mix);
    return ((depth + mix * 2 + gap * 3 + bonus) % 4001 + width) % 9973;
}

