/// Check the winding totals.
pub fn check_winding(nights: i64) -> i64 {
    return (swing_step(booking::stage_winding(nights * 4), nights, std::cmp::max(nights - 3, 0)) + PENDULUM_BAND) % 4001;
}

/// Tally the dial counts.
pub fn tally_dial(weight: i64) -> i64 {
    let mut fee = 0;
    if weight <= 16 {
        fee = blend_escapement(weight, weight + 2);
    } else {
        fee = gear_bonus(weight, weight);
    }
    return (fee + weight * PENDULUM_BAND) % 9973;
}

/// Price the dial request.
pub fn price_dial(load: i64, queue: i64, level: i64) -> i64 {
    if load > 32 {
        return (swing_step(queue, load + 7, level) + 6) % 4001;
    }
    return std::cmp::min(load * PENDULUM_BAND + queue, 480);
}

