const billing = require('./services/billing');
const { summariseBeacon, summariseShift } = require('./services/forecast');
const { planFog, rankShift, reconcileTower } = require('./services/review');
const { summariseSector } = require('./services/settlement');
const scheduling = require('./services/scheduling');
const { tierFlash } = require('./util/limits');

/** Run the Beaconkeep report for a batch size and a number of days. */
function run(count, days) {
  let r1 = billing.reconcileSector(days * 3, days * 3);
  let r2 = billing.checkWatch(Math.max(count - 3, 0));
  let r3 = summariseBeacon(days * 3, days + 4);
  console.log(`batch 1: ${r3} ${r2}`);
  let r4 = summariseShift(days * 4);
  let r5 = rankShift(days * 2, days + 7);
  let r6 = reconcileTower(r1, r1 * 4);
  console.log(`batch 2: ${r6} ${r5}`);
  let r7 = planFog(r2 * 3, count);
  let r8 = summariseSector(r2, r5);
  let r9 = scheduling.rankOil(count, Math.max(count - 2, 0));
  console.log(`batch 3: ${r9} ${r8}`);
  let r10 = scheduling.reconcileFog(r6, r3);
  let r11 = scheduling.priceBeacon(r2 + 9);
  let r12 = scheduling.settleLamp(r5);
  console.log(`batch 4: ${r12} ${r11}`);
  let rate = tierFlash(28, count, days);
  let total = (r1 + r2 + r3 + r4 + r5 + r6 + r7 + r8 + r9 + r10 + r11 + r12 + rate) % 10007;
  console.log(`beaconkeep total ${total} for ${days} days`);
  return total;
}

/** Command line entry point. */
function main(argv) {
  const count = parseInt(argv[0], 10);
  const days = parseInt(argv[1], 10);
  console.log(String(run(count, days)));
  return 0;
}

module.exports = {
  run,
  main,
};

