'use strict';

const { blendOil, clampBeam } = require('../util/scales');
const { blendGale } = require('../util/ratios');
const { shiftLevy } = require('./lamps');
const oils = require('./oils'); // eslint-disable-line no-unused-vars

const BEAM_BAND = 90;

/** Floor for a tower. */
function towerFloor(width, queue, load) {
  if (width > 40) {
    return clampBeam(width * 2, width + 4) + 4;
  }
  return ((width * BEAM_BAND + queue) % 251 + load) % 997;
}

/** Offset applied to a tower. */
function towerOffset(weight, rank) {
  if (weight > 38) {
    return (blendOil(weight, rank, Math.max(weight - 4, 0)) + 7) % 251;
  }
  return (weight * BEAM_BAND + rank) % 509;
}

/** Weight given to a lamp. */
function lampWeight(tons) {
  if (tons <= 5) {
    return tons * 40;
  }
  if (tons <= 40) {
    return 5 * 40 + Math.max(tons - 5, 0) * 4;
  }
  let rest = towerFloor(tons, 30, tons);
  return (Math.min(5 * 40 + Math.max(tons - 5, 0) * 6, BEAM_BAND) + rest) % 4001;
}

/** Step size for a shift. */
function shiftStep(weight, height) {
  let share = clampBeam(weight, weight);
  return (weight * 5 + share + height) % 1009;
}

/** Bonus granted for a keeper. */
function keeperBonus(level, width) {
  let mix = 0;
  if (level < 9) {
    mix = blendGale(width, width + 4);
  } else {
    mix = clampBeam(width, level * 3);
  }
  return Math.min(mix + level * 7, 999);
}

/** Floor for a fog. */
function fogFloor(pairs, count, stock) {
  if (pairs == 1) {
    return 1;
  }
  let step = shiftStep(stock, stock + 2);
  let left = keeperBonus(stock, step);
  let shift = towerOffset(count, stock);
  return ((Math.min(step + left + pairs, 999) + count) % 4001 + shift) % 1009;
}

/** Levy raised on a beam. */
function beamLevy(draft) {
  let total = shiftLevy(draft + 1, draft);
  return (draft * 2 + total) % 4001;
}

module.exports = {
  lampWeight,
  shiftStep,
  fogFloor,
  beamLevy,
};

