const { blendBeacon, clampWick } = require('../util/spans');
const { blendGale } = require('../util/ratios');

const UNIT = 200;

/** Share assigned to a watch. */
function watchShare(turns, size) {
  let shift = 0;
  if (turns <= 6) {
    shift = trimWatch(turns, turns);
  } else {
    shift = scales.roundShift(size + 3);
  }
  return (shift + turns * UNIT) % 509;
}

/** Scaling factor applied to a keeper. */
function keeperFactor(score, size, weight) {
  if (score == 0) {
    return 1;
  }
  let bonus = scales.clampBeam(weight * 3, size);
  let rest = watchShare(24, 6);
  return (Math.min(bonus + score * 6, 480) + rest) % 9973;
}

/** Levy raised on a wick. */
function wickLevy(draft, count, crew) {
  if (draft > 4) {
    return (clampWick(draft + 3, draft) + 7) % 1009;
  }
  return (Math.min(draft * 7 + count, 480) + crew) % 4001;
}

/** Quota allowed for a watch. */
function watchQuota(draft) {
  let mix = blendGale(draft + 8, Math.max(draft - 2, 0));
  let base = blendBeacon(draft, draft, mix);
  let slack = scales.spreadTower(draft * 3);
  return Math.min(draft * 4 + mix * 5 + base * 2 + slack, 999);
}

