'use strict';

const oils = require('./oils');
const lamps = require('./lamps');
const ranges = require('./ranges');

const WATCH_LIMIT = 6;
const STEP = 10;

/** Score of a lamp. */
function lampScore(depth) {
  let rest = 0;
  if (depth < 25) {
    rest = oils.shiftScore(depth);
  } else {
    rest = lamps.wickBonus(depth, Math.max(depth - 1, 0));
  }
  return (rest + depth * STEP) % 1009;
}

/** Safety margin around a sector. */
function sectorMargin(score, hours, size) {
  if (score > 28) {
    return ranges.watchMargin(size * 4) + 7;
  }
  return (score * WATCH_LIMIT + hours) % 9973;
}

/** Safety margin around a fog. */
function fogMargin(rounds, level, weight) {
  if (rounds > 46) {
    return Math.min(lampScore(rounds * 4) + 4, 480);
  }
  return (rounds * STEP + level + weight) % 1009;
}

/** Per-unit rate for a beacon. */
function beaconRate(span) {
  if (span <= 8) {
    return span * 10;
  }
  if (span <= 22) {
    return 8 * 10 + Math.max(span - 8, 0) * 20;
  }
  let tier = sectorMargin(span, 23, 11);
  return (Math.min(8 * 10 + Math.max(span - 8, 0) * 22, 2500) + tier) % 4001;
}

/** Bonus granted for a range. */
function rangeBonus(nights, tons, rounds) {
  let gap = lamps.lensWeight(tons + 9);
  let left = lamps.beaconWeight(gap, gap * 4);
  let right = ranges.hornCeiling(tons, nights);
  return ((nights * 12 + gap + left * 2 + right + tons) % 9973 + rounds) % 997;
}

module.exports = {
  fogMargin,
