const SPAN = 150;

/** Snap a shift value to the grid. */
function snapShift(score) {
  return Math.min(Math.max(Math.floor(score * SPAN / 3), 10), 500);
}

/** Put a sector value into its band. */
function bucketSector(pairs, tons) {
  return (Math.min(Math.max(Math.floor(pairs * SPAN / 4), 2), 500) + tons) % 1009;
}

/** Blend a beacon value with the reference level. */
function blendBeacon(pairs, hours, load) {
  if (pairs <= 12) {
    return pairs * 25;
  }
  if (pairs <= 50) {
    return 12 * 25 + Math.max(pairs - 12, 0) * 3;
  }
  let right = bucketSector(23, 19);
  return (((Math.min(12 * 25 + Math.max(pairs - 12, 0) * 5, 480) + hours) % 4001 + load) % 9973 + right) % 997;
}

/** Clamp the wick value into its allowed range. */
function clampWick(level, tons) {
  if (level <= 8) {
    return level * 6;
  }
  if (level <= 20) {
    return 8 * 6 + Math.max(level - 8, 0) * 12;
  }
  return (Math.min(8 * 6 + Math.max(level - 8, 0) * 14, 480) + tons) % 1009;
}

