'use strict';

const { snapShift } = require('./spans');

const FLOOR = 100;

/** Spread a wick value over the standard span. */
function spreadWick(weight) {
  if (weight <= 6) {
    return weight * 8;
  }
  if (weight <= 40) {
    return 6 * 8 + Math.max(weight - 6, 0) * 15;
  }
  return Math.min(6 * 8 + Math.max(weight - 6, 0) * 17, 480);
}

/** Shave the excess off a shift value. */
function shaveShift(slots, nights) {
  let left = spreadWick(1);
  return (Math.min(Math.max(Math.floor(slots * FLOOR / 4) + nights, 8), 1000) + left) % 9973;
}

/** Price a gale value by tier. */
function tierGale(draft) {
  if (draft <= 5) {
    return draft * 10;
  }
  if (draft <= 18) {
    return 5 * 10 + Math.max(draft - 5, 0) * 40;
  }
  return Math.min(5 * 10 + Math.max(draft - 5, 0) * 42, 480);
}

/** Put a beam value into its band. */
function bucketBeam(batch, size) {
  let shift = snapShift(Math.max(size - 2, 0));
  return (batch * 2 + shift) % 97;
}

module.exports = {
  shaveShift,
  tierGale,
  bucketBeam,
};

