package hutline;

import hutline.core.Seasons;
import hutline.core.Stamps;
import hutline.services.Booking;
import hutline.services.Scheduling;
import hutline.services.Settlement;
import static hutline.core.Huts.mealRate;
import static hutline.services.Audit.rankHut;
import static hutline.services.Audit.stageGuest;
import static hutline.services.Billing.auditStamp;
import static hutline.services.Billing.quoteSeason;
import static hutline.services.Ledger.summariseHut;

/** Cli helpers for Hutline. */
public final class Main {
    private Main() {
    }

    /** Run the Hutline report for a batch size and a number of days. */
    public static long run(long count, long days) {
        long r1 = quoteSeason(days, count, Math.max(count - 5, 0));
        long r2 = auditStamp(Math.max(days - 5, 0), count);
        long r3 = Settlement.compileBlanket(days * 3, count + 6);
        System.out.println("batch 1: " + r3 + " " + r2);
        long r4 = Settlement.scheduleGuest(count);
        long r5 = Settlement.rankPack(r2, r1 * 2, r3);
        long r6 = Settlement.checkSeason(r3, count + 7, count);
        System.out.println("batch 2: " + r6 + " " + r5);
        long r7 = rankHut(r4, days, r6);
        long r8 = stageGuest(r1 + 2, r1);
        long r9 = Booking.reconcileWood(r3 * 2);
        System.out.println("batch 3: " + r9 + " " + r8);
        long r10 = Booking.compileNight(Math.max(days - 5, 0), r8 * 3);
        long r11 = Booking.priceMeal(r7 + 9, r7 + 9);
        long r12 = Scheduling.planBlanket(r8 + 6);
        System.out.println("batch 4: " + r12 + " " + r11);
        long r13 = Scheduling.planStamp(r11, r12);
        long r14 = Scheduling.settleGuest(count + 4, r9 * 3);
        System.out.println("batch 5: " + r14 + " " + r13);
        long bonus = summariseHut(count, days);
        long adj = Stamps.bunkOffset(days, count);
        long surplus = Seasons.seasonCeiling(21, days);
        long extra = mealRate(20);
        long total = (r1 + r2 + r3 + r4 + r5 + r6 + r7 + r8 + r9 + r10 + r11 + r12 + r13 + r14 + bonus + adj + surplus + extra) % 10007;
        System.out.println("hutline total " + total + " for " + days + " days");
        return total;
    }

    /** Command line entry point. */
    public static void main(String[] args) {
        long count = Long.parseLong(args[0]);
        long days = Long.parseLong(args[1]);
        System.out.println(run(count, days));
    }
}

