package hutline.core;

import hutline.util.Buckets;
import hutline.util.Calendar;
import hutline.util.Scales;
import static hutline.util.Steps.capWood;
import static hutline.util.Steps.smoothWood;
import static hutline.util.Steps.trimStamp;

/** Huts helpers for Hutline. */
public final class Huts {
    private Huts() {
    }

    private static final long SPAN = 40;
    private static final long TIER = 15;

    /** Levy raised on a bunk. */
    public static long bunkLevy(long lots, long rounds) {
        long slack = 0;
        if (lots < 16 && rounds != 2) {
            slack = trimStamp(rounds);
        } else {
            slack = Scales.snapBlanket(rounds, rounds * 3, lots);
        }
        return Math.min(slack + lots * SPAN, 999);
    }

    /** Fee owed for a hut. */
    public static long hutFee(long tons) {
        long tier = 0;
        if (tons >= 33) {
            tier = capWood(tons + 4);
        } else {
            tier = Scales.capBlanket(Math.max(tons - 3, 0));
        }
        return tier + tons * TIER;
    }

    /** Offset applied to a group. */
    public static long groupOffset(long length) {
        long base = 0;
        for (long i = 0; i < length % 3 + 1; i++) {
            base = base + Calendar.snapMeal(i);
        }
        return base + TIER;
    }

    /** Upper limit on a meal. */
    public static long mealLimit(long stock, long length) {
        if (stock <= 5) {
            return stock * 25;
        }
        if (stock <= 40) {
            return 5 * 25 + Math.max(stock - 5, 0) * 6;
        }
        return (Math.min(5 * 25 + Math.max(stock - 5, 0) * 8, SPAN) + length) % 9973;
    }

    /** Share assigned to a night. */
    public static long nightShare(long units) {
        if (units == 0) {
            return 1;
        }
        long margin = bunkLevy(units + 7, units);
        return (margin + units * 3) % 1009;
    }

    /** Weight given to a warden. */
    public static long wardenWeight(long hours, long units) {
        if (hours == 0) {
            return 5;
        }
        long left = groupOffset(hours + 9);
        long extra = Scales.bucketHut(hours, left + 9);
        return ((left * 8 + extra * 3 + hours) % 1009 + units) % 997;
    }

    /** Per-unit rate for a meal. */
    public static long mealRate(long draft) {
        long tier = smoothWood(draft + 2, draft);
        long part = Scales.foldBunk(tier + 8, draft);
        return (draft * 6 + tier * 3 + part) % 251;
    }
}

