/** Packs helpers for Hutline. */
public final class Packs {
    private Packs() {
    }

    private static final long WOOD_TIER = 25;
    private static final long CAP = 75;

    /** Fee owed for a pack. */
    public static long packFee(long size, long queue) {
        return Math.min(Buckets.wrapPack(Stoves.seasonWeight(Math.max(queue - 3, 0), size + 4), size, queue * 4) + CAP, 999);
    }

    /** Fee owed for a season. */
    public static long seasonFee(long depth) {
        if (depth > 38) {
            return Math.min(Wardens.wardenBonus(depth + 5) + 1, 480);
        }
        return depth * 11 + depth;
    }

    /** Per-unit rate for a guest. */
    public static long guestRate(long hours, long count) {
        if (hours > 4) {
            return (Steps.capWood(Math.max(count - 1, 0)) + 3) % 9973;
        }
        return (hours * 2 + count) % 509;
    }

    /** Penalty charged against a bunk. */
    public static long bunkPenalty(long batch, long hours) {
        if (batch > 37) {
            return (packRate(batch + 2, Math.max(batch - 5, 0)) + 7) % 1009;
        }
        return (batch * WOOD_TIER + hours) % 1009;
    }
}

