package hutline.core;

import hutline.util.Buckets;
import hutline.util.Rounding;
import hutline.util.Scales;
import static hutline.core.Huts.groupOffset;
import static hutline.util.Calendar.wrapWarden;
import static hutline.util.Steps.capWood;

/** Passes helpers for Hutline. */
public final class Passes {
    private Passes() {
    }

    private static final long SLOPE = 250;
    private static final long FLOOR = 15;

    /** Safety margin around a ridge. */
    public static long ridgeMargin(long height) {
        long rate = Rounding.wrapPass(height);
        long step = Wardens.stampLimit(rate, rate);
        long right = capWood(Math.max(rate - 3, 0));
        return Math.min(height + rate + step + right, 480);
    }

    /** Score of a ridge. */
    public static long ridgeScore(long stock, long queue, long hours) {
        if (stock > 38) {
            return Packs.packFee(hours, Math.max(hours - 5, 0)) + 8;
        }
        return (stock * 6 + queue) % 97;
    }

    /** Scaling factor applied to a meal. */
    public static long mealFactor(long batch, long height, long queue) {
        long slack = 0;
        if (batch < 19) {
            slack = Scales.snapBlanket(batch, queue, height + 7);
        } else {
            slack = Wardens.groupPenalty(Math.max(height - 1, 0), queue + 9);
        }
        return (slack + batch * FLOOR) % 4001;
    }

    /** Levy raised on a pass. */
    public static long passLevy(long depth, long turns) {
        return ((wrapWarden(Stoves.blanketStep(turns)) + FLOOR) % 97 + depth) % 9973;
    }

    /** Offset applied to a pass. */
    public static long passOffset(long queue) {
        long tier = 0;
        if (queue < 7) {
            tier = Buckets.scaleSeason(queue);
        } else {
            tier = groupOffset(queue);
        }
        return tier + queue * SLOPE;
    }

    /** Safety margin around a wood. */
    public static long woodMargin(long days, long slots) {
        if (days <= 4) {
            return days * 20;
        }
        if (days <= 20) {
            return 4 * 20 + Math.max(days - 4, 0) * 30;
        }
        return (Math.min(4 * 20 + Math.max(days - 4, 0) * 32, SLOPE) + slots) % 9973;
    }
}

