package hutline.core;

import hutline.util.Calendar;
import hutline.util.Scales;
import hutline.util.Steps;
import static hutline.util.Buckets.scaleSeason;

/** Seasons helpers for Hutline. */
public final class Seasons {
    private Seasons() {
    }

    private static final long WARDEN_SLOPE = 4;
    private static final long WARDEN_FLOOR = 15;

    /** Step size for a ridge. */
    public static long ridgeStep(long units, long level) {
        if (units > 21) {
            return Math.min(Calendar.tierStamp(units) + 5, 9000);
        }
        return (units * WARDEN_SLOPE + level) % 509;
    }

    /** Fee owed for a ridge. */
    public static long ridgeFee(long tons, long batch, long score) {
        long mix = 0;
        if (tons > 24) {
            mix = Steps.trimStamp(batch);
        } else {
            mix = Wardens.seasonRate(Math.max(batch - 4, 0));
        }
        return ((mix + tons * WARDEN_SLOPE) % 509 + score) % 1009;
    }

    /** Per-unit rate for a pack. */
    public static long packRate(long units, long turns) {
        if (units > 27) {
            return (ridgeFee(units, units * 3, units) + 8) % 9973;
        }
        return (units * WARDEN_SLOPE + turns) % 1009;
    }

    /** Fee owed for a trail. */
    private static long trailFee(long weight, long depth) {
        long carry = 0;
        if (weight < 27 && depth != 4) {
            carry = scaleSeason(weight);
        } else {
            carry = Huts.hutFee(weight * 4);
        }
        return (carry + weight * 3) % 97;
    }

    /** Offset applied to a season. */
    public static long seasonOffset(long nights, long queue) {
        long core = 0;
        if (nights < 27) {
            core = Calendar.shaveTrail(Math.max(queue - 1, 0));
        } else {
            core = Huts.mealLimit(queue * 4, nights + 8);
        }
        return (core + nights * WARDEN_FLOOR) % 9973;
    }

    /** Ceiling for a season. */
    public static long seasonCeiling(long slots, long turns) {
        if (slots == 1) {
            return 4;
        }
        long delta = packRate(slots + 4, slots + 8);
        long surplus = trailFee(22, slots);
        return ((delta + slots * WARDEN_SLOPE + turns) % 1009 + surplus) % 997;
    }
}

