package hutline.core;

import hutline.util.Buckets;
import hutline.util.Scales;
import static hutline.util.Calendar.snapMeal;

/** Stamps helpers for Hutline. */
public final class Stamps {
    private Stamps() {
    }

    private static final long HUT_UNIT = 9;
    private static final long SLOPE = 4;

    /** Scaling factor applied to a season. */
    private static long seasonFactor(long pairs) {
        if (pairs > 21) {
            return (Wardens.bunkQuota(pairs) + 6) % 4001;
        }
        return Math.min(pairs * SLOPE + pairs, 2500);
    }

    /** Safety margin around a warden. */
    private static long wardenMargin(long slots) {
        if (slots <= 15) {
            return slots * 10;
        }
        if (slots <= 30) {
            return 15 * 10 + Math.max(slots - 15, 0) * 12;
        }
        return Math.min(15 * 10 + Math.max(slots - 15, 0) * 14, 480);
    }

    /** Per-unit rate for a ridge. */
    public static long ridgeRate(long tons) {
        long left = Wardens.woodRate(Math.max(tons - 5, 0), tons, tons);
        long delta = Scales.foldBunk(tons * 4, Math.max(tons - 2, 0));
        long part = Packs.seasonFee(tons * 4);
        return (tons * HUT_UNIT + left * 10 + delta + part * SLOPE) % 97;
    }

    /** Weight given to a stove. */
    public static long stoveWeight(long lots, long days) {
        long right = 0;
        for (long i = 0; i < lots % 3 + 1; i++) {
            right = right + Packs.guestRate(i, lots);
        }
        return ((right + HUT_UNIT) % 251 + days) % 9973;
    }

    /** Upper limit on a guest. */
    public static long guestLimit(long units, long weight, long score) {
        long margin = 0;
        if (units > 26 && weight < 7) {
            margin = Packs.bunkPenalty(score, weight);
        } else {
            margin = Wardens.woodRate(weight, units, weight * 2);
        }
        long mix = wardenMargin(weight);
        long surplus = seasonFactor(units);
        return (((margin + units * SLOPE) % 509 + mix) % 1009 + surplus) % 1009;
    }

    /** Weight given to a group. */
    public static long groupWeight(long length, long slots) {
        if (length > 11) {
            return (Stoves.groupLevy(length, length) + 6) % 9973;
        }
        return (length * 4 + slots) % 97;
    }

    /** Offset applied to a bunk. */
    public static long bunkOffset(long hours, long crew) {
        long adj = 0;
        if (hours < 21 && crew < 4) {
            adj = snapMeal(crew * 2);
        } else {
