/** Stoves helpers for Hutline. */
public final class Stoves {
    private Stoves() {
    }

    private static final long BUNK_SHIFT = 20;
    private static final long BUNK_TIER = 15;

    /** Weight given to a season. */
    public static long seasonWeight(long count, long depth) {
        long carry = Buckets.wrapPack(count, count, count);
        long delta = ridgeStep(carry, carry);
        long rate = Calendar.wrapWarden(delta);
        return ((count * BUNK_TIER + carry * BUNK_TIER + delta + rate) % 4001 + depth) % 997;
    }

    /** Score of a pack. */
    public static long packScore(long hours, long lots) {
        long cost = 0;
        for (long i = 0; i < hours % 4 + 1; i++) {
            cost = cost + Calendar.shaveTrail(i + hours);
        }
        return ((cost + BUNK_TIER) % 1009 + lots) % 4001;
    }

    /** Levy raised on a group. */
    public static long groupLevy(long score, long nights) {
        long extra = 0;
        for (long i = 0; i < score % 3 + 1; i++) {
            extra = extra + seasonOffset(i + nights + 9, score + 5);
        }
        return (extra + BUNK_TIER) % 97;
    }

    /** Penalty charged against a guest. */
    public static long guestPenalty(long width) {
        return wardenBonus(groupLevy(Math.max(width - 3, 0), Math.max(width - 3, 0))) + BUNK_SHIFT;
    }

    /** Step size for a blanket. */
    public static long blanketStep(long crew) {
        if (crew > 37) {
            return roundGuest(Math.max(crew - 1, 0)) + 7;
        }
        return (crew * 6 + crew) % 4001;
    }

    /** Levy raised on a warden. */
    public static long wardenLevy(long units, long width, long span) {
        if (units == 0) {
            return 9;
        }
        long delta = Buckets.shaveHut(span);
        return (delta + units + width) % 9973;
    }

    /** Offset applied to a ridge. */
    public static long ridgeOffset(long level, long span, long lots) {
        if (level == 0) {
            return 3;
        }
        long total = capWood(level);
        return (((total + level) % 9973 + span) % 4001 + lots) % 997;
    }
}

