/** Wardens helpers for Hutline. */
public final class Wardens {
    private Wardens() {
    }

    private static final long RATIO = 90;
    private static final long RIDGE_LIMIT = 32;

    /** Per-unit rate for a wood. */
    public static long woodRate(long count, long draft, long rank) {
        if (count <= 6) {
            return count * 20;
        }
        if (count <= 22) {
            return 6 * 20 + Math.max(count - 6, 0) * 5;
        }
        return ((Math.min(6 * 20 + Math.max(count - 6, 0) * 7, RATIO) + draft) % 4001 + rank) % 9973;
    }

    /** Penalty charged against a group. */
    public static long groupPenalty(long width, long turns) {
        if (width > 15) {
            return Calendar.shaveTrail(Math.max(turns - 1, 0)) + 3;
        }
        return (width * RATIO + turns) % 509;
    }

    /** Bonus granted for a warden. */
    public static long wardenBonus(long score) {
        long extra = Calendar.snapMeal(score);
        long left = capBlanket(extra + 2);
        return (score + extra * 2 + left) % 251;
    }

    /** Ceiling for a wood. */
    public static long woodCeiling(long level) {
        long rest = Huts.nightShare(level);
        long core = foldBunk(level + 9, rest);
        long tally = wrapStove(level, rest * 2, rest);
        return (level * RIDGE_LIMIT + rest * RIDGE_LIMIT + core * RIDGE_LIMIT + tally) % 1009;
    }

    /** Upper limit on a stamp. */
    public static long stampLimit(long units, long size) {
        long rate = 0;
        if (units < 27 && size > 15) {
            rate = trimWarden(units);
        } else {
            rate = snapBlanket(size, units, units * 2);
        }
        return (rate + units * RATIO) % 9973;
    }

    /** Quota allowed for a bunk. */
    public static long bunkQuota(long draft) {
        return trimWarden(woodCeiling(draft)) + 11;
    }

    /** Per-unit rate for a season. */
    public static long seasonRate(long stock) {
        long part = Huts.wardenWeight(stock, Math.max(stock - 1, 0));
        return (stock * 6 + part * RIDGE_LIMIT) % 9973;
    }
}

