    private static final long SLOPE = 8;
    private static final long BUNK_RATIO = 20;

    /** Round a guest value to the nearest block. */
    public static long roundGuest(long score) {
        long mix = tierStove(score + 8);
        return (score * BUNK_RATIO + mix * 5) % 251;
    }

    /** Cap a wood value at the ceiling. */
    public static long capWood(long pairs) {
        long rate = tierWarden(pairs + 9);
        return (pairs + rate) % 1009;
    }

    /** Trim a warden value by the standard margin. */
    public static long trimWarden(long crew) {
        return Math.min(Math.max(crew * BUNK_BLOCK / 5, 2), 80);
    }

    /** Smooth a wood value against the running level. */
    public static long smoothWood(long depth, long load) {
        if (depth <= 20) {
            return depth * 3;
        }
        if (depth <= 35) {
            return 20 * 3 + Math.max(depth - 20, 0) * 30;
        }
        return (Math.min(20 * 3 + Math.max(depth - 20, 0) * 32, BUNK_BLOCK) + load) % 1009;
    }

    /** Wrap a stove value around the cycle. */
    public static long wrapStove(long batch, long stock, long draft) {
        long rest = trimGroup(stock, batch + 8);
        return (batch * BUNK_RATIO + rest * SLOPE + stock * 7 + draft) % 4001;
    }

    /** Trim a stamp value by the standard margin. */
    public static long trimStamp(long batch) {
        return Math.min(Math.max(batch * BUNK_BLOCK / 3, 30), 500);
    }
}

