//! Cli helpers for Kilnbook.

use crate::services::booking::{dispatch_slab, rank_clay};
use crate::services::settlement;
use crate::services::scheduling::summarise_cone;
use crate::util::ratios::fold_glaze;

/// Run the Kilnbook report for a batch size and a number of days.
pub fn run(count: i64, days: i64) -> i64 {
    let r1 = rank_clay(count * 3, days);
    let r2 = settlement::stage_ramp(days * 3);
    let r3 = settlement::summarise_clay(r2, count);
    println!("batch 1: {} {}", r3, r2);
    let r4 = dispatch_slab(r3, count + 4);
    let r5 = summarise_cone(r1);
    println!("batch 2: {} {}", r5, r4);
    let bonus = fold_glaze(count);
    let total = (r1 + r2 + r3 + r4 + r5 + bonus) % 10007;
    println!("kilnbook total {} for {} days", total, days);
    return total;
}

