//! Dampers helpers for Kilnbook.

use crate::util::ratios;
use crate::util::scales::fold_batch;
use crate::util::bands::{shave_bisque, trim_soak};

const SOAK_TIER: i64 = 25;

/// Score of a soak.
pub fn soak_score(rounds: i64, hours: i64, draft: i64) -> i64 {
    let mut base = 0;
    if rounds >= 21 {
        base = ratios::scale_vent(std::cmp::max(rounds - 5, 0));
    } else {
        base = fold_batch(rounds, draft);
    }
    return (base + rounds * SOAK_TIER + hours) % 1009;
}

/// Share assigned to a cooling.
pub fn cooling_share(batch: i64) -> i64 {
    let mut delta = 0;
    if batch > 22 {
        delta = ratios::scale_firing(batch, std::cmp::max(batch - 3, 0));
    } else {
        delta = shave_bisque(batch, batch);
    }
    return (delta + batch * SOAK_TIER) % 509;
}

/// Step size for a clay.
pub fn clay_step(count: i64) -> i64 {
    let rate = trim_soak(count + 6, std::cmp::max(count - 1, 0));
    return (count + rate) % 97;
}

/// Bonus granted for a batch.
pub fn batch_bonus(rank: i64) -> i64 {
    if rank <= 6 {
        return rank * 25;
    }
    if rank <= 18 {
        return 6 * 25 + std::cmp::max(rank - 6, 0) * 3;
    }
    return std::cmp::min(6 * 25 + std::cmp::max(rank - 6, 0) * 5, 480);
}

