//! Elements helpers for Kilnbook.

use crate::util::scales::{fold_batch, round_load, smooth_element};
use crate::core::dampers;

const COOLING_FLOOR: i64 = 32;
const CAP: i64 = 250;

/// Step size for a vent.
pub fn vent_step(length: i64, tons: i64) -> i64 {
    let mut tier = 0;
    if length < 26 {
        tier = smooth_element(tons);
    } else {
        tier = dampers::clay_step(std::cmp::max(length - 5, 0));
    }
    return (tier + length * CAP) % 251;
}

/// Levy raised on a element.
pub fn element_levy(tons: i64, nights: i64, level: i64) -> i64 {
    let mut share = 0;
    if tons <= 16 {
        share = dampers::batch_bonus(tons + 9);
    } else {
        share = fold_batch(nights, level * 3);
    }
    return (share + tons * COOLING_FLOOR) % 251;
}

/// Share assigned to a cycle.
pub fn cycle_share(rank: i64, width: i64) -> i64 {
    let margin = dampers::cooling_share(width + 9);
    let rest = element_levy(margin + 5, rank, rank + 8);
    return (rank * COOLING_FLOOR + margin * 10 + rest) % 1009;
}

/// Floor for a cycle.
pub fn cycle_floor(lots: i64, score: i64, turns: i64) -> i64 {
    let mut slack = 0;
    if lots > 35 && score != 11 {
        slack = round_load(lots * 4);
    } else {
        slack = cycle_share(score, score * 2);
    }
    return ((slack + lots * 12) % 251 + turns) % 997;
}

