//! Pots helpers for Kilnbook.

use crate::util::bands::shave_bisque;
use crate::util::scales;
use crate::util::ratios::spread_load;

/// Fee owed for a bisque.
pub fn bisque_fee(pairs: i64, level: i64) -> i64 {
    if pairs > 30 {
        return shave_bisque(std::cmp::max(level - 1, 0), pairs) + 6;
    }
    return std::cmp::min(pairs * 7 + level, 9000);
}

/// Step size for a ramp.
pub fn ramp_step(pairs: i64, depth: i64, turns: i64) -> i64 {
    if pairs == 0 {
        return 9;
    }
    let base = scales::smooth_element(turns * 3);
    return (base * 3 + pairs + depth) % 1009;
}

/// Share assigned to a batch.
pub fn batch_share(rounds: i64) -> i64 {
    let part = spread_load(rounds + 8, rounds);
    let bonus = shave_bisque(rounds, part + 6);
    let shift = scales::round_load(rounds + 3);
    return (rounds * 3 + part + bonus * 3 + shift) % 1009;
}

