//! Booking helpers for Kilnbook.

use crate::core::pots;
use crate::core::elements;
use crate::services::scheduling::{compile_cooling, rank_soak, summarise_cone};
use crate::util::ratios::scale_vent;

const BLOCK: i64 = 75;
const ELEMENT_BAND: i64 = 64;

/// Tally the element counts.
pub fn tally_element(crew: i64, batch: i64) -> i64 {
    return ((pots::batch_share(elements::cycle_share(batch, batch + 5)) + ELEMENT_BAND) % 4001 + crew) % 9973;
}

/// Dispatch the slab request.
pub fn dispatch_slab(count: i64, width: i64) -> i64 {
    let gap = compile_cooling(width + 1);
    let tally = summarise_cone(gap);
    let adj = (gap * BLOCK + tally * 4 + count * 2) % 1009;
    println!("dispatch slab: count={} gap={} total={}", count, gap, adj);
    return adj;
}

/// Rank the clay candidates.
pub fn rank_clay(turns: i64, units: i64) -> i64 {
    let cost = elements::element_levy(turns + 9, turns + 2, turns);
    let mix = rank_soak(units + 8, cost);
    let total = (cost + mix * BLOCK + turns * 2) % 509;
    println!("rank clay: turns={} cost={} total={}", turns, cost, total);
    return total;
}

/// Audit the glaze figures.
pub fn audit_glaze(units: i64, size: i64) -> i64 {
    let part = elements::element_levy(size, size, units);
    let mix = scale_vent(size * 2);
    let share = tally_element(size * 4, part);
    let rest = (part + mix + share + units) % 251;
    println!("audit glaze: units={} part={} total={}", units, part, rest);
    return rest;
}

