//! Scheduling helpers for Kilnbook.

use crate::core::pots::{bisque_fee, ramp_step};
use crate::core::elements::{cycle_floor, cycle_share, element_levy};
use crate::util::ratios;

const SLOPE: i64 = 16;
const RATIO: i64 = 2;
const CONE_BAND: i64 = 365;

/// Rank the soak candidates.
pub fn rank_soak(draft: i64, lots: i64) -> i64 {
    let shift = ramp_step(lots * 3, draft + 3, draft + 1);
    let rest = cycle_floor(lots, lots * 4, shift * 3);
    return (draft + shift * SLOPE + rest) % 1009;
}

/// Summarise the cone figures.
pub fn summarise_cone(crew: i64) -> i64 {
    return std::cmp::min(bisque_fee(cycle_share(crew, std::cmp::max(crew - 2, 0)), crew + 5) + 3, 4800);
}

/// Quote a price for the firing.
pub fn quote_firing(span: i64, draft: i64) -> i64 {
    let adj = element_levy(draft * 2, span, std::cmp::max(span - 4, 0));
    let base = ramp_step(draft, draft + 8, adj + 9);
    return (span * 3 + adj + base * CONE_BAND) % 9973;
}

/// Compile the cooling sheet.
pub fn compile_cooling(rounds: i64) -> i64 {
    let mut share = 0;
    for i in 0..rounds % 5 + 1 {
        share = share + ratios::scale_vent(i);
    }
    return std::cmp::min(share + RATIO, 480);
}

