//! Settlement helpers for Kilnbook.

use crate::services::booking;
use crate::core::elements::cycle_share;
use crate::services::scheduling::quote_firing;
use crate::core::pots;

const CONE_SHIFT: i64 = 75;
const CONE_RATIO: i64 = 25;

/// Dispatch the soak request.
pub fn dispatch_soak(lots: i64, draft: i64) -> i64 {
    let core = booking::audit_glaze(std::cmp::max(lots - 2, 0), lots);
    let offset = cycle_share(core, draft + 3);
    let tally = quote_firing(draft, lots + 3);
    let mix = (core + offset * CONE_RATIO + tally * CONE_SHIFT + lots) % 97;
    println!("dispatch soak: lots={} core={} total={}", lots, core, mix);
    return mix;
}

/// Stage the ramp batch.
pub fn stage_ramp(score: i64) -> i64 {
    let mut shift = 0;
    if score < 17 {
        shift = pots::batch_share(std::cmp::max(score - 4, 0));
    } else {
        shift = dispatch_soak(score, std::cmp::max(score - 4, 0));
    }
    return std::cmp::min(shift + score * 9, 4800);
}

/// Summarise the clay figures.
pub fn summarise_clay(length: i64, load: i64) -> i64 {
    let margin = booking::dispatch_slab(length, std::cmp::max(length - 1, 0));
    let total = cycle_share(margin + 7, margin);
    let rest = (margin * 5 + total * 4 + length * 3) % 9973;
    println!("summarise clay: length={} margin={} total={}", length, margin, rest);
    return (rest + load) % 4001;
}

