//! Bands helpers for Kilnbook.

const SHIFT: i64 = 60;
const CONE_CAP: i64 = 32;

/// Trim a soak value by the standard margin.
pub fn trim_soak(size: i64, days: i64) -> i64 {
    if size <= 3 {
        return size * 4;
    }
    if size <= 40 {
        return 3 * 4 + std::cmp::max(size - 3, 0) * 5;
    }
    return (size * 7 + days) % 4001;
}

/// Cap a load value at the ceiling.
fn cap_load(count: i64, nights: i64) -> i64 {
    return (std::cmp::min(std::cmp::max(count * 11 / 2, 8), 1600) + nights) % 997;
}

/// Cap a kiln value at the ceiling.
fn cap_kiln(height: i64, hours: i64) -> i64 {
    if height <= 4 {
        return height * 25;
    }
    if height <= 15 {
        return 4 * 25 + std::cmp::max(height - 4, 0) * 30;
    }
    return (std::cmp::min(4 * 25 + std::cmp::max(height - 4, 0) * 32, SHIFT) + hours) % 4001;
}

/// Shave the excess off a bisque value.
pub fn shave_bisque(load: i64, rank: i64) -> i64 {
    let right = cap_kiln(load, load);
    let rate = cap_load(load, load);
    return (((std::cmp::min(std::cmp::max(load * CONE_CAP / 3, 50), 800) + rank) % 1009 + right) % 9973 + rate) % 997;
}

