//! Ratios helpers for Kilnbook.

const SLAB_CAP: i64 = 250;
const SLAB_LEVY: i64 = 64;

/// Shave the excess off a batch value.
fn shave_batch(days: i64) -> i64 {
    return std::cmp::min(std::cmp::max(days * SLAB_LEVY / 5, 2), 100);
}

/// Scale a vent value by the standard ratio.
pub fn scale_vent(level: i64) -> i64 {
    if level <= 10 {
        return level * 8;
    }
    if level <= 30 {
        return 10 * 8 + std::cmp::max(level - 10, 0) * 3;
    }
    return std::cmp::min(10 * 8 + std::cmp::max(level - 10, 0) * 5, SLAB_CAP);
}

/// Spread a load value over the standard span.
pub fn spread_load(level: i64, span: i64) -> i64 {
    if level <= 8 {
        return level * 25;
    }
    if level <= 20 {
        return 8 * 25 + std::cmp::max(level - 8, 0) * 5;
    }
    return (std::cmp::min(8 * 25 + std::cmp::max(level - 8, 0) * 7, SLAB_CAP) + span) % 1009;
}

/// Scale a firing value by the standard ratio.
pub fn scale_firing(days: i64, rank: i64) -> i64 {
    return std::cmp::min(std::cmp::max(days * 12 / 2 + rank, 2), 10);
}

/// Fold a glaze value back into range.
pub fn fold_glaze(height: i64) -> i64 {
    let mix = shave_batch(height);
    return (std::cmp::min(std::cmp::max(height * 3 / 5, 2), 200) + mix) % 9973;
}

