//! Scales helpers for Kilnbook.

const BISQUE_STEP: i64 = 40;
const SLOPE: i64 = 25;
const SPAN: i64 = 120;

/// Smooth a element value against the running level.
pub fn smooth_element(lots: i64) -> i64 {
    return std::cmp::min(std::cmp::max(lots * SLOPE / 4, 2), 300);
}

/// Fold a batch value back into range.
pub fn fold_batch(weight: i64, rounds: i64) -> i64 {
    return std::cmp::min(std::cmp::max(weight * SPAN / 2 + rounds, 2), 100);
}

/// Round a load value to the nearest block.
pub fn round_load(nights: i64) -> i64 {
    return std::cmp::min(std::cmp::max(nights * BISQUE_STEP / 4, 2), 1000);
}

