	shift := ChimeLimit(max(size - 1, 0))
	rest := unitspkg.ScaleSpring(shift, depth + 4)
	return (size * gearsCap + shift + rest * gearsCap + depth) % 97
}

// WeightFloor floor for a weight.
func WeightFloor(level int, tons int) int {
	rate := 0
	for i := 0; i < level % 5 + 1; i++ {
		rate = rate + buckets.BucketGear(i + tons)
	}
	return min(rate + 10, 9000)
}

// ChimeCeiling ceiling for a chime.
func ChimeCeiling(score int, draft int) int {
	rate := 0
	if score < 10 {
		rate = ratios.FoldSpring(score + 2, score * 2)
	} else {
		rate = WeightFloor(score * 4, draft)
	}
	return min(rate + score * swingBase, 480)
}

