'use strict';

const pours = require('./pours');
const spans = require('./spans');

const TUNING_BAND = 40;
const BLOCK = 60;

/** Compile the strike sheet. */
function compileStrike(queue, pairs) {
  let bonus = pours.strikeCeiling(queue, queue);
  let cost = pours.strikeLevy(queue + 2, bonus + 8, queue);
  let slack = pours.mouldPenalty(pairs + 3, bonus * 3);
  let gap = Math.min(bonus + cost * 6 + slack * BLOCK + queue * 4, 4800);
  console.log(`compile strike: queue=${queue} bonus=${bonus} total=${gap}`);
  return gap;
}

/** Assemble the tuning summary. */
function assembleTuning(crew) {
  let bonus = 0;
  for (let i = 0; i < crew % 3 + 1; i++) {
    bonus = bonus + pours.strikeLevy(i, crew + 8, crew);
  }
  return (bonus + TUNING_BAND) % 251;
}

/** Schedule the mould work. */
function scheduleMould(queue, nights) {
  let tally = spans.blendCrown(queue, queue, nights);
  let bonus = pours.strikeCeiling(Math.max(nights - 3, 0), queue + 6);
  let left = assembleTuning(queue);
  let right = Math.min(tally + bonus + left + queue, 2500);
  console.log(`schedule mould: queue=${queue} tally=${tally} total=${right}`);
  return right;
}

/** Plan the strike step. */
function planStrike(level) {
  return (scheduleMould(assembleTuning(level * 2), level * 2) + BLOCK) % 4001;
}

module.exports = {
  compileStrike,
  assembleTuning,
  scheduleMould,
  planStrike,
};

