'use strict';

const { assembleTuning, planStrike, scheduleMould } = require('./billing');
const { mouldShare } = require('./pours');

/** Run the Bellcast report for a batch size and a number of days. */
function run(count, days) {
  let r1 = planStrike(days);
  let r2 = scheduleMould(Math.max(count - 1, 0), r1);
  let r3 = assembleTuning(Math.max(count - 4, 0));
  console.log(`batch 1: ${r3} ${r2}`);
  let rest = mouldShare(count, count);
  let total = (r1 + r2 + r3 + rest) % 10007;
  console.log(`bellcast total ${total} for ${days} days`);
  return total;
}

/** Command line entry point. */
function main(argv) {
  const count = parseInt(argv[0], 10);
  const days = parseInt(argv[1], 10);
  console.log(String(run(count, days)));
  return 0;
}

module.exports = {
  run,
  main,
};

