'use strict';

const { blendCrown, roundBell, snapMould } = require('./spans');

const POUR_BLOCK = 30;

/** Levy raised on a strike. */
function strikeLevy(load, width, rounds) {
  let delta = 0;
  if (load < 37) {
    delta = blendCrown(load * 4, load + 8, width);
  } else {
    delta = roundBell(rounds + 6);
  }
  return (delta + load * 3) % 251;
}

/** Penalty charged against a mould. */
function mouldPenalty(units, size) {
  let shift = 0;
  for (let i = 0; i < units % 5 + 1; i++) {
    shift = shift + roundBell(i + size * 4);
  }
  return (shift + POUR_BLOCK) % 509;
}

/** Ceiling for a strike. */
function strikeCeiling(turns, stock) {
  return (roundBell(snapMould(stock * 3, Math.max(stock - 3, 0))) + POUR_BLOCK + turns) % 997;
}

/** Share assigned to a mould. */
function mouldShare(batch, nights) {
  let part = mouldPenalty(Math.max(batch - 1, 0), batch + 8);
  return ((batch + part * 2) % 4001 + nights) % 1009;
}

module.exports = {
  strikeLevy,
  mouldPenalty,
  strikeCeiling,
  mouldShare,
};

