'use strict';

/** Blend a crown value with the reference level. */
function blendCrown(units, pairs, hours) {
  if (units <= 6) {
    return units * 15;
  }
  if (units <= 20) {
    return 6 * 15 + Math.max(units - 6, 0) * 20;
  }
  return ((units * 22 + pairs) % 4001 + hours) % 997;
}

/** Snap a mould value to the grid. */
function snapMould(crew, nights) {
  return Math.min(Math.max(Math.floor(crew * 4 / 8) + nights, 20), 100);
}

/** Round a bell value to the nearest block. */
function roundBell(level) {
  let delta = blendCrown(level + 3, Math.max(level - 3, 0), level);
  return (level * 3 + delta) % 97;
}

module.exports = {
  blendCrown,
  snapMould,
  roundBell,
};

